-- Phase 3+ schema foundation: orders, production, quality, dispatch, workforce, finance and platform queues.
ALTER DEFAULT PRIVILEGES IN SCHEMA public REVOKE ALL ON TABLES FROM PUBLIC,anon,authenticated;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS is_demo boolean NOT NULL DEFAULT false;
ALTER TABLE public.departments ADD COLUMN IF NOT EXISTS source text NOT NULL DEFAULT 'LIVE';
ALTER TABLE public.employees ADD COLUMN IF NOT EXISTS source text NOT NULL DEFAULT 'LIVE';
ALTER TABLE public.buyers ADD COLUMN IF NOT EXISTS source text NOT NULL DEFAULT 'LIVE';
ALTER TABLE public.purchase_orders ADD COLUMN IF NOT EXISTS is_demo boolean NOT NULL DEFAULT false;
ALTER TABLE public.purchase_receipts ADD COLUMN IF NOT EXISTS is_demo boolean NOT NULL DEFAULT false;
ALTER TABLE public.yarn_batches ADD COLUMN IF NOT EXISTS is_demo boolean NOT NULL DEFAULT false;
ALTER TABLE public.inventory_movements ADD COLUMN IF NOT EXISTS is_demo boolean NOT NULL DEFAULT false;
ALTER TABLE public.material_reservations ADD COLUMN IF NOT EXISTS is_demo boolean NOT NULL DEFAULT false;
ALTER TABLE public.stock_adjustments ADD COLUMN IF NOT EXISTS is_demo boolean NOT NULL DEFAULT false;
ALTER TABLE public.cycle_counts ADD COLUMN IF NOT EXISTS is_demo boolean NOT NULL DEFAULT false;
ALTER TABLE public.cycle_count_lines ADD COLUMN IF NOT EXISTS is_demo boolean NOT NULL DEFAULT false;
ALTER TABLE public.wip_lots ADD COLUMN IF NOT EXISTS is_demo boolean NOT NULL DEFAULT false;
ALTER TABLE public.cost_entries ADD COLUMN IF NOT EXISTS is_demo boolean NOT NULL DEFAULT false;

DO $$ BEGIN CREATE TYPE public.order_status AS ENUM ('DRAFT','CONFIRMED','PLANNED','IN_PRODUCTION','READY_FOR_DISPATCH','PARTIALLY_DISPATCHED','DISPATCHED','CLOSED','CANCELLED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.order_priority AS ENUM ('LOW','NORMAL','HIGH','URGENT'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.plan_status AS ENUM ('DRAFT','PENDING_MATERIAL','RELEASED','IN_PROGRESS','COMPLETED','CANCELLED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.op_status AS ENUM ('PLANNED','READY','IN_PROGRESS','PAUSED','COMPLETED','CANCELLED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.roll_status AS ENUM ('IN_PRODUCTION','AWAITING_INSPECTION','REWORK_REQUIRED','REWORK_IN_PROGRESS','REINSPECTION_REQUIRED','ACCEPTED','REJECTED','QUARANTINED','RESERVED','DISPATCHED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.inspection_result AS ENUM ('PASS','REWORK','REJECT','QUARANTINE'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.shipment_status AS ENUM ('DRAFT','ALLOCATED','CONFIRMED','CANCELLED','REVERSED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.shipment_roll_status AS ENUM ('ALLOCATED','SCANNED','DISPATCHED','RELEASED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.exception_status AS ENUM ('OPEN','ACKNOWLEDGED','IN_PROGRESS','RESOLVED','SUPPRESSED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.severity AS ENUM ('INFO','LOW','MEDIUM','HIGH','CRITICAL'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.automation_mode AS ENUM ('OFF','DRY_RUN','SUGGEST','DRAFT','NOTIFY','EXECUTE'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.approval_request_status AS ENUM ('PENDING','APPROVED','REJECTED','CHANGES_REQUESTED','CANCELLED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.attendance_status AS ENUM ('PRESENT','ABSENT','LEAVE','LATE','HALF_DAY'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.payroll_status AS ENUM ('DRAFT','CALCULATED','APPROVED','LOCKED','REOPENED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;

CREATE TABLE IF NOT EXISTS public.approval_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),request_type text NOT NULL,entity_type text NOT NULL,entity_id uuid,payload jsonb NOT NULL DEFAULT '{}'::jsonb,requested_by uuid NOT NULL REFERENCES public.profiles(id),reason text NOT NULL DEFAULT '',required_permission text NOT NULL,status public.approval_request_status NOT NULL DEFAULT 'PENDING',decided_by uuid REFERENCES public.profiles(id),decided_at timestamptz,decision_note text,deadline timestamptz,impact_summary jsonb NOT NULL DEFAULT '{}'::jsonb,is_demo boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,type text NOT NULL,severity public.severity NOT NULL DEFAULT 'INFO',title text NOT NULL,body text NOT NULL,entity_type text,entity_id uuid,action_url text,dedupe_key text,read_at timestamptz,is_demo boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,dedupe_key));
CREATE TABLE IF NOT EXISTS public.notification_preferences (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,event_type text NOT NULL,channel text NOT NULL CHECK(channel IN ('in_app','email','whatsapp')),enabled boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,event_type,channel));
CREATE TABLE IF NOT EXISTS public.email_outbox (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),to_email text NOT NULL,template text NOT NULL,payload jsonb NOT NULL DEFAULT '{}'::jsonb,status text NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','SENT','FAILED','DEAD')),attempts integer NOT NULL DEFAULT 0,next_attempt_at timestamptz,last_error text,idempotency_key uuid NOT NULL UNIQUE,provider_message_id text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.integration_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),provider text NOT NULL,event_key text NOT NULL UNIQUE,status text NOT NULL DEFAULT 'PENDING',attempts integer NOT NULL DEFAULT 0,last_error text,payload jsonb NOT NULL DEFAULT '{}'::jsonb,is_simulated boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.exceptions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),exception_no text NOT NULL UNIQUE,type text NOT NULL,severity public.severity NOT NULL,status public.exception_status NOT NULL DEFAULT 'OPEN',dedupe_key text NOT NULL,title text NOT NULL,reason text NOT NULL,entity_type text,entity_id uuid,owner_user_id uuid REFERENCES public.profiles(id),owner_role text,opened_at timestamptz NOT NULL DEFAULT now(),due_at timestamptz,escalation_level integer NOT NULL DEFAULT 0,escalated_at timestamptz,resolved_at timestamptz,resolved_by uuid REFERENCES public.profiles(id),occurrence_count integer NOT NULL DEFAULT 1,suggested_action jsonb NOT NULL DEFAULT '{}'::jsonb,is_demo boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS exceptions_open_dedupe_idx ON public.exceptions(dedupe_key) WHERE status NOT IN ('RESOLVED','SUPPRESSED');
CREATE TABLE IF NOT EXISTS public.tasks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),task_no text NOT NULL UNIQUE,title text NOT NULL,description text NOT NULL DEFAULT '',assignee_user_id uuid REFERENCES public.profiles(id),assignee_role text,due_at timestamptz,status text NOT NULL DEFAULT 'OPEN' CHECK(status IN ('OPEN','IN_PROGRESS','DONE','CANCELLED')),entity_type text,entity_id uuid,checklist jsonb NOT NULL DEFAULT '[]'::jsonb,evidence_file_id uuid,source_exception_id uuid REFERENCES public.exceptions(id),source_automation text,created_by uuid REFERENCES public.profiles(id),completed_at timestamptz,is_demo boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.files (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),bucket text NOT NULL,object_path text NOT NULL UNIQUE,original_name text NOT NULL,mime text NOT NULL,size_bytes bigint NOT NULL CHECK(size_bytes>=0),checksum text,entity_type text,entity_id uuid,uploaded_by uuid REFERENCES public.profiles(id),status text NOT NULL DEFAULT 'UPLOADED' CHECK(status IN ('UPLOADED','FAILED','DELETED')),is_demo boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),doc_type text NOT NULL,entity_type text NOT NULL,entity_id uuid,version integer NOT NULL DEFAULT 1,file_id uuid REFERENCES public.files(id),status text NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','GENERATED','FAILED')),attempts integer NOT NULL DEFAULT 0,last_error text,buyer_shareable boolean NOT NULL DEFAULT false,generated_at timestamptz,is_demo boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.automation_rules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code text NOT NULL UNIQUE CHECK(code ~ '^A(0[1-9]|[12][0-9]|30)$'),name text NOT NULL,mode public.automation_mode NOT NULL DEFAULT 'OFF',enabled boolean NOT NULL DEFAULT false,owner_role text,config jsonb NOT NULL DEFAULT '{}'::jsonb,last_run_at timestamptz,last_result jsonb,next_run_at timestamptz,failure_reason text,retry_count integer NOT NULL DEFAULT 0,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.automation_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),rule_code text NOT NULL,event_key text NOT NULL UNIQUE,payload jsonb NOT NULL DEFAULT '{}'::jsonb,status text NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','DONE','FAILED')),attempts integer NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.automation_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),rule_code text NOT NULL,event_key text NOT NULL,dry_run boolean NOT NULL,status text NOT NULL,result jsonb NOT NULL DEFAULT '{}'::jsonb,error text,started_at timestamptz NOT NULL DEFAULT now(),finished_at timestamptz,UNIQUE(rule_code,event_key));
CREATE TABLE IF NOT EXISTS public.reconciliation_reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),run_at timestamptz NOT NULL DEFAULT now(),run_by uuid REFERENCES public.profiles(id),status text NOT NULL,discrepancies jsonb NOT NULL DEFAULT '[]'::jsonb,summary jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE IF NOT EXISTS public.data_quality_flags (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),type text NOT NULL,entity_type text NOT NULL,entity_id uuid,detail jsonb NOT NULL DEFAULT '{}'::jsonb,status text NOT NULL DEFAULT 'OPEN' CHECK(status IN ('OPEN','FIXED','IGNORED')),detected_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.assistant_queries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public.profiles(id),question text NOT NULL,intent text,sources jsonb NOT NULL DEFAULT '[]'::jsonb,created_at timestamptz NOT NULL DEFAULT now());

CREATE TABLE IF NOT EXISTS public.employee_compensation (employee_id uuid PRIMARY KEY REFERENCES public.employees(id),wage_basis text NOT NULL CHECK(wage_basis IN ('MONTHLY','DAILY','HOURLY','SHIFT')),wage_rate numeric(16,2) NOT NULL CHECK(wage_rate>=0),currency text NOT NULL DEFAULT 'INR',overtime_multiplier numeric(6,3) NOT NULL DEFAULT 1.5 CHECK(overtime_multiplier>=1),updated_by uuid REFERENCES public.profiles(id),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.skills (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code text NOT NULL UNIQUE,name text NOT NULL,is_active boolean NOT NULL DEFAULT true,source text NOT NULL DEFAULT 'LIVE',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.employee_skills (employee_id uuid NOT NULL REFERENCES public.employees(id),skill_id uuid NOT NULL REFERENCES public.skills(id),certified_until date,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(employee_id,skill_id));
CREATE TABLE IF NOT EXISTS public.process_skills (process_id uuid NOT NULL REFERENCES public.process_definitions(id),skill_id uuid NOT NULL REFERENCES public.skills(id),required boolean NOT NULL DEFAULT true,PRIMARY KEY(process_id,skill_id));

CREATE TABLE IF NOT EXISTS public.buyer_orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_number text NOT NULL UNIQUE,buyer_id uuid NOT NULL REFERENCES public.buyers(id),requested_date date NOT NULL,promised_date date,status public.order_status NOT NULL DEFAULT 'DRAFT',priority public.order_priority NOT NULL DEFAULT 'NORMAL',currency text NOT NULL DEFAULT 'INR',notes_internal text NOT NULL DEFAULT '',notes_buyer text NOT NULL DEFAULT '',over_delivery_pct numeric(6,3) NOT NULL DEFAULT 0 CHECK(over_delivery_pct>=0),feasibility_status text,version integer NOT NULL DEFAULT 1,confirmed_by uuid REFERENCES public.profiles(id),confirmed_at timestamptz,cancel_reason text,created_by uuid REFERENCES public.profiles(id),source text NOT NULL DEFAULT 'LIVE',is_demo boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.buyer_order_lines (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL REFERENCES public.buyer_orders(id) ON DELETE CASCADE,line_no integer NOT NULL,product_id uuid NOT NULL REFERENCES public.products(id),colour text NOT NULL DEFAULT '',ordered_qty numeric(14,3) NOT NULL CHECK(ordered_qty>0),unit text NOT NULL,unit_rate numeric(16,2) NOT NULL CHECK(unit_rate>=0),spec_overrides jsonb NOT NULL DEFAULT '{}'::jsonb,is_demo boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(order_id,line_no));
CREATE TABLE IF NOT EXISTS public.order_revisions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL REFERENCES public.buyer_orders(id),field text NOT NULL,old_value jsonb,new_value jsonb,reason text NOT NULL,changed_by uuid REFERENCES public.profiles(id),changed_at timestamptz NOT NULL DEFAULT now(),is_demo boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS public.order_change_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL REFERENCES public.buyer_orders(id),requested_by uuid NOT NULL REFERENCES public.profiles(id),request_type text NOT NULL CHECK(request_type IN ('QUANTITY','COLOUR_SPEC','DELIVERY_DATE')),payload jsonb NOT NULL,impact_analysis jsonb NOT NULL DEFAULT '{}'::jsonb,status public.approval_request_status NOT NULL DEFAULT 'PENDING',decided_by uuid REFERENCES public.profiles(id),is_demo boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.feasibility_checks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL REFERENCES public.buyer_orders(id),result text NOT NULL CHECK(result IN ('READY','READY_WITH_RISKS','BLOCKED')),details jsonb NOT NULL DEFAULT '{}'::jsonb,created_by uuid REFERENCES public.profiles(id),override_reason text,overridden_by uuid REFERENCES public.profiles(id),is_demo boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.production_plans (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),plan_no text NOT NULL UNIQUE,order_line_id uuid NOT NULL REFERENCES public.buyer_order_lines(id),planned_qty numeric(14,3) NOT NULL CHECK(planned_qty>0),expected_yield_pct numeric(6,3) NOT NULL DEFAULT 100 CHECK(expected_yield_pct>0 AND expected_yield_pct<=100),planned_start timestamptz,planned_end timestamptz,status public.plan_status NOT NULL DEFAULT 'DRAFT',override_reason text,released_by uuid REFERENCES public.profiles(id),released_at timestamptz,estimated_completion timestamptz,completion_factors jsonb NOT NULL DEFAULT '{}'::jsonb,created_by uuid REFERENCES public.profiles(id),is_demo boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.plan_material_requirements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),plan_id uuid NOT NULL REFERENCES public.production_plans(id) ON DELETE CASCADE,yarn_item_id uuid NOT NULL REFERENCES public.yarn_items(id),required_qty numeric(14,3) NOT NULL,available_snapshot numeric(14,3) NOT NULL DEFAULT 0,shortage_qty numeric(14,3) NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(plan_id,yarn_item_id));
CREATE TABLE IF NOT EXISTS public.production_operations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),operation_no text NOT NULL UNIQUE,plan_id uuid NOT NULL REFERENCES public.production_plans(id),process_id uuid NOT NULL REFERENCES public.process_definitions(id),stage text NOT NULL,sequence integer NOT NULL,status public.op_status NOT NULL DEFAULT 'PLANNED',is_not_applicable boolean NOT NULL DEFAULT false,machine_id uuid REFERENCES public.machines(id),shift_id uuid REFERENCES public.shifts(id),supervisor_id uuid REFERENCES public.employees(id),planned_start timestamptz,planned_end timestamptz,actual_start timestamptz,actual_end timestamptz,target_qty numeric(14,3) NOT NULL DEFAULT 0,unit text NOT NULL,previous_operation_id uuid REFERENCES public.production_operations(id),waiting_reason text,at_risk boolean NOT NULL DEFAULT false,pause_reason text,created_by uuid REFERENCES public.profiles(id),is_demo boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(plan_id,sequence));
CREATE TABLE IF NOT EXISTS public.operation_assignments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),operation_id uuid NOT NULL REFERENCES public.production_operations(id) ON DELETE CASCADE,employee_id uuid NOT NULL REFERENCES public.employees(id),role_on_operation text NOT NULL DEFAULT 'OPERATOR',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(operation_id,employee_id));
CREATE TABLE IF NOT EXISTS public.operation_materials (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),operation_id uuid NOT NULL REFERENCES public.production_operations(id),yarn_batch_id uuid REFERENCES public.yarn_batches(id),reservation_id uuid REFERENCES public.material_reservations(id),planned_qty numeric(14,3) NOT NULL DEFAULT 0,actual_qty numeric(14,3) NOT NULL DEFAULT 0,unit_cost_snapshot numeric(16,2),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.operation_wip_inputs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),operation_id uuid NOT NULL REFERENCES public.production_operations(id),wip_lot_id uuid REFERENCES public.wip_lots(id),roll_id uuid,qty numeric(14,3) NOT NULL CHECK(qty>0),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.operation_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),operation_id uuid NOT NULL REFERENCES public.production_operations(id),event_type text NOT NULL CHECK(event_type IN ('START','PAUSE','RESUME','COMPLETE','CANCEL','CORRECTION','ASSIGN')),reason text,created_by uuid REFERENCES public.profiles(id),created_at timestamptz NOT NULL DEFAULT now(),is_demo boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS public.production_outputs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),operation_id uuid NOT NULL REFERENCES public.production_operations(id),shift_instance_id uuid NOT NULL REFERENCES public.shift_instances(id),work_date date NOT NULL,good_qty numeric(14,3) NOT NULL DEFAULT 0 CHECK(good_qty>=0),waste_qty numeric(14,3) NOT NULL DEFAULT 0 CHECK(waste_qty>=0),reject_qty numeric(14,3) NOT NULL DEFAULT 0 CHECK(reject_qty>=0),unit text NOT NULL,waste_reason text,reject_reason text,notes text NOT NULL DEFAULT '',recorded_by uuid REFERENCES public.profiles(id),recorded_at timestamptz NOT NULL DEFAULT now(),idempotency_key uuid NOT NULL UNIQUE,corrects_output_id uuid REFERENCES public.production_outputs(id),correction_reason text,status text NOT NULL DEFAULT 'RECORDED' CHECK(status IN ('RECORDED','SUPERSEDED','VOID')),is_demo boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS public.shift_handovers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),handover_no text NOT NULL UNIQUE,shift_instance_id uuid NOT NULL REFERENCES public.shift_instances(id),outgoing_supervisor uuid REFERENCES public.employees(id),incoming_supervisor uuid REFERENCES public.employees(id),summary jsonb NOT NULL DEFAULT '{}'::jsonb,notes text,status text NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','SUBMITTED','ACKNOWLEDGED')),acknowledged_by uuid REFERENCES public.profiles(id),acknowledged_at timestamptz,is_demo boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.waste_ledger (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),operation_id uuid REFERENCES public.production_operations(id),machine_id uuid REFERENCES public.machines(id),shift_instance_id uuid REFERENCES public.shift_instances(id),order_id uuid REFERENCES public.buyer_orders(id),process_id uuid REFERENCES public.process_definitions(id),waste_type text NOT NULL,qty numeric(14,3) NOT NULL CHECK(qty>=0),unit text NOT NULL,reason text NOT NULL,resource_water_l numeric(14,3),resource_energy_kwh numeric(14,3),resource_chemical_kg numeric(14,3),is_demo boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());

CREATE TABLE IF NOT EXISTS public.machine_status_log (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),machine_id uuid NOT NULL REFERENCES public.machines(id),from_status text,to_status text NOT NULL,changed_by uuid REFERENCES public.profiles(id),reason text,created_at timestamptz NOT NULL DEFAULT now(),is_demo boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS public.downtime_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),downtime_no text NOT NULL UNIQUE,machine_id uuid NOT NULL REFERENCES public.machines(id),operation_id uuid REFERENCES public.production_operations(id),reason_id uuid REFERENCES public.downtime_reasons(id),severity public.severity NOT NULL DEFAULT 'MEDIUM',started_at timestamptz NOT NULL DEFAULT now(),ended_at timestamptz,duration_minutes numeric(14,3),status text NOT NULL DEFAULT 'OPEN' CHECK(status IN ('OPEN','CLOSED')),reported_by uuid REFERENCES public.profiles(id),notes text,is_simulated boolean NOT NULL DEFAULT false,is_demo boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),CHECK(ended_at IS NULL OR ended_at>=started_at));
CREATE TABLE IF NOT EXISTS public.maintenance_schedules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),machine_id uuid NOT NULL REFERENCES public.machines(id),type text NOT NULL,interval_days integer CHECK(interval_days>=0),interval_hours numeric(14,3) CHECK(interval_hours>=0),next_due timestamptz,is_demo boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.maintenance_work_orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),wo_number text NOT NULL UNIQUE,machine_id uuid NOT NULL REFERENCES public.machines(id),type text NOT NULL CHECK(type IN ('PREVENTIVE','CORRECTIVE')),status text NOT NULL DEFAULT 'OPEN' CHECK(status IN ('OPEN','SCHEDULED','IN_PROGRESS','COMPLETED','CANCELLED')),due_at timestamptz,window_start timestamptz,window_end timestamptz,completed_at timestamptz,cost numeric(16,2),assigned_to uuid REFERENCES public.employees(id),downtime_event_id uuid REFERENCES public.downtime_events(id),spares_ready boolean NOT NULL DEFAULT false,approved_by uuid REFERENCES public.profiles(id),is_demo boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.maintenance_parts_used (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),wo_id uuid NOT NULL REFERENCES public.maintenance_work_orders(id),part_id uuid NOT NULL REFERENCES public.spare_parts(id),qty numeric(14,3) NOT NULL CHECK(qty>0),unit_cost numeric(16,2) NOT NULL CHECK(unit_cost>=0),is_demo boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.machine_telemetry (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),machine_id uuid NOT NULL REFERENCES public.machines(id),metric text NOT NULL,value numeric(18,6) NOT NULL,unit text NOT NULL,recorded_at timestamptz NOT NULL,event_key text NOT NULL UNIQUE,is_simulated boolean NOT NULL DEFAULT true,is_demo boolean NOT NULL DEFAULT false);

CREATE TABLE IF NOT EXISTS public.fabric_rolls (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),roll_code text NOT NULL UNIQUE,qr_token text NOT NULL UNIQUE,order_line_id uuid NOT NULL REFERENCES public.buyer_order_lines(id),plan_id uuid NOT NULL REFERENCES public.production_plans(id),created_by_operation_id uuid REFERENCES public.production_operations(id),output_id uuid REFERENCES public.production_outputs(id),qty numeric(14,3) NOT NULL CHECK(qty>0),unit text NOT NULL DEFAULT 'm',status public.roll_status NOT NULL DEFAULT 'IN_PRODUCTION',current_stage text,location_id uuid REFERENCES public.stock_locations(id),prior_status public.roll_status,hold_reason text,first_pass_result boolean,version integer NOT NULL DEFAULT 1,created_by uuid REFERENCES public.profiles(id),is_demo boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.roll_material_sources (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),roll_id uuid NOT NULL REFERENCES public.fabric_rolls(id),yarn_batch_id uuid REFERENCES public.yarn_batches(id),dye_lot_id uuid,qty_fraction numeric(9,6) NOT NULL CHECK(qty_fraction>=0 AND qty_fraction<=1),is_demo boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.roll_genealogy (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),parent_roll_id uuid NOT NULL REFERENCES public.fabric_rolls(id),child_roll_id uuid NOT NULL REFERENCES public.fabric_rolls(id),relationship_type text NOT NULL CHECK(relationship_type IN ('SPLIT','MERGE')),qty numeric(14,3) NOT NULL CHECK(qty>0),is_demo boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),CHECK(parent_roll_id<>child_roll_id));
CREATE TABLE IF NOT EXISTS public.dye_lots (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),lot_code text NOT NULL UNIQUE,colour text NOT NULL,operation_id uuid REFERENCES public.production_operations(id),parameters jsonb NOT NULL DEFAULT '{}'::jsonb,status text NOT NULL DEFAULT 'OK' CHECK(status IN ('OK','HOLD')),notes text,is_demo boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE public.roll_material_sources ADD CONSTRAINT roll_material_dye_fk FOREIGN KEY(dye_lot_id) REFERENCES public.dye_lots(id);
CREATE TABLE IF NOT EXISTS public.roll_dye_lots (roll_id uuid NOT NULL REFERENCES public.fabric_rolls(id),dye_lot_id uuid NOT NULL REFERENCES public.dye_lots(id),PRIMARY KEY(roll_id,dye_lot_id));
CREATE TABLE IF NOT EXISTS public.roll_status_history (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),roll_id uuid NOT NULL REFERENCES public.fabric_rolls(id),from_status public.roll_status,to_status public.roll_status NOT NULL,reason text,actor uuid REFERENCES public.profiles(id),created_at timestamptz NOT NULL DEFAULT now(),is_demo boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS public.roll_scan_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),roll_id uuid NOT NULL REFERENCES public.fabric_rolls(id),user_id uuid REFERENCES public.profiles(id),context text NOT NULL CHECK(context IN ('LOOKUP','INSPECT','MOVE','DISPATCH','COUNT')),scanned_at timestamptz NOT NULL DEFAULT now(),is_demo boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS public.quality_inspections (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),inspection_no text NOT NULL UNIQUE,roll_id uuid NOT NULL REFERENCES public.fabric_rolls(id),operation_id uuid REFERENCES public.production_operations(id),plan_id uuid REFERENCES public.inspection_plans(id),inspector_id uuid REFERENCES public.profiles(id),inspection_stage text NOT NULL CHECK(inspection_stage IN ('GREIGE','FINAL','REINSPECTION')),round integer NOT NULL DEFAULT 1,is_reinspection boolean NOT NULL DEFAULT false,prior_inspection_id uuid REFERENCES public.quality_inspections(id),sample_size numeric(14,3),result public.inspection_result NOT NULL,inspected_at timestamptz NOT NULL DEFAULT now(),notes text,evidence_pending boolean NOT NULL DEFAULT false,is_demo boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS public.quality_inspection_measurements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),inspection_id uuid NOT NULL REFERENCES public.quality_inspections(id),check_id uuid REFERENCES public.inspection_plan_checks(id),measured_value numeric(14,3),expected_min numeric(14,3),expected_max numeric(14,3),unit text NOT NULL,pass boolean NOT NULL,is_demo boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS public.quality_defects (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),inspection_id uuid NOT NULL REFERENCES public.quality_inspections(id),defect_category_id uuid NOT NULL REFERENCES public.defect_categories(id),severity public.severity NOT NULL,quantity_or_extent numeric(14,3),unit text,pos_x numeric(7,3),pos_y numeric(7,3),notes text,evidence_file_id uuid REFERENCES public.files(id),is_demo boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.rework_orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),rework_no text NOT NULL UNIQUE,roll_id uuid NOT NULL REFERENCES public.fabric_rolls(id),source_inspection_id uuid NOT NULL REFERENCES public.quality_inspections(id),status text NOT NULL DEFAULT 'OPEN' CHECK(status IN ('OPEN','IN_PROGRESS','COMPLETED','CANCELLED')),assigned_to uuid REFERENCES public.employees(id),started_at timestamptz,completed_at timestamptz,notes text,cost numeric(16,2),is_demo boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.quality_incidents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),incident_no text NOT NULL UNIQUE,trigger text NOT NULL CHECK(trigger IN ('DEFECT_THRESHOLD','SUSPECT_BATCH','MANUAL')),status text NOT NULL DEFAULT 'OPEN' CHECK(status IN ('OPEN','INVESTIGATING','CONTAINED','CLOSED')),root_cause text,details jsonb NOT NULL DEFAULT '{}'::jsonb,opened_by uuid REFERENCES public.profiles(id),closed_at timestamptz,is_demo boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.quality_incident_rolls (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),incident_id uuid NOT NULL REFERENCES public.quality_incidents(id),roll_id uuid REFERENCES public.fabric_rolls(id),shipment_id uuid,order_id uuid REFERENCES public.buyer_orders(id),genealogy_complete boolean NOT NULL DEFAULT true,action_taken text,is_demo boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS public.corrective_actions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),incident_id uuid NOT NULL REFERENCES public.quality_incidents(id),type text NOT NULL CHECK(type IN ('SUPPLIER','MACHINE','PROCESS')),description text NOT NULL,owner_id uuid REFERENCES public.employees(id),due_date date,status text NOT NULL DEFAULT 'OPEN',is_demo boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());

CREATE TABLE IF NOT EXISTS public.shipments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),shipment_number text NOT NULL UNIQUE,order_id uuid NOT NULL REFERENCES public.buyer_orders(id),status public.shipment_status NOT NULL DEFAULT 'DRAFT',planned_at timestamptz,dispatched_at timestamptz,carrier text,vehicle_no text,tracking_reference text,requested_qty numeric(14,3) NOT NULL DEFAULT 0,manifest_expected_count integer NOT NULL DEFAULT 0,manifest_scanned_count integer NOT NULL DEFAULT 0,scan_mismatch_ack boolean NOT NULL DEFAULT false,scan_mismatch_reason text,needs_attention boolean NOT NULL DEFAULT false,suggested_by_automation boolean NOT NULL DEFAULT false,buyer_visible boolean NOT NULL DEFAULT false,confirmed_by uuid REFERENCES public.profiles(id),idempotency_key uuid UNIQUE,created_by uuid REFERENCES public.profiles(id),is_demo boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.shipment_rolls (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),shipment_id uuid NOT NULL REFERENCES public.shipments(id),roll_id uuid NOT NULL REFERENCES public.fabric_rolls(id),order_line_id uuid NOT NULL REFERENCES public.buyer_order_lines(id),allocated_qty numeric(14,3) NOT NULL CHECK(allocated_qty>0),status public.shipment_roll_status NOT NULL DEFAULT 'ALLOCATED',scanned_at timestamptz,is_demo boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS shipment_rolls_active_unique_idx ON public.shipment_rolls(roll_id) WHERE status IN ('ALLOCATED','SCANNED','DISPATCHED');
CREATE TABLE IF NOT EXISTS public.shipment_scan_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),shipment_id uuid NOT NULL REFERENCES public.shipments(id),roll_code text NOT NULL,result text NOT NULL CHECK(result IN ('MATCHED','NOT_ON_MANIFEST','DUPLICATE','INVALID')),scanned_by uuid REFERENCES public.profiles(id),scanned_at timestamptz NOT NULL DEFAULT now(),is_demo boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS public.shipment_suggestions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL REFERENCES public.buyer_orders(id),roll_ids uuid[] NOT NULL,reason jsonb NOT NULL DEFAULT '{}'::jsonb,status text NOT NULL DEFAULT 'OPEN' CHECK(status IN ('OPEN','ACCEPTED','DISMISSED')),event_key text UNIQUE,is_demo boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.invoices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),invoice_number text NOT NULL UNIQUE,shipment_id uuid REFERENCES public.shipments(id),order_id uuid NOT NULL REFERENCES public.buyer_orders(id),invoice_date date NOT NULL,due_date date,currency text NOT NULL DEFAULT 'INR',subtotal numeric(16,2) NOT NULL,tax_rate numeric(7,4) NOT NULL DEFAULT 0,tax_amount numeric(16,2) NOT NULL DEFAULT 0,total numeric(16,2) NOT NULL,status text NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','ISSUED','VOID','CREDITED')),approved_by uuid REFERENCES public.profiles(id),is_demo boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.dispatch_reversals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),shipment_id uuid NOT NULL REFERENCES public.shipments(id),reason text NOT NULL,approval_id uuid REFERENCES public.approval_requests(id),created_by uuid REFERENCES public.profiles(id),is_demo boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());

CREATE TABLE IF NOT EXISTS public.attendance_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),employee_id uuid NOT NULL REFERENCES public.employees(id),shift_id uuid NOT NULL REFERENCES public.shifts(id),work_date date NOT NULL,status public.attendance_status NOT NULL,check_in timestamptz,check_out timestamptz,overtime_minutes integer NOT NULL DEFAULT 0 CHECK(overtime_minutes>=0),approval_status public.approval_request_status NOT NULL DEFAULT 'PENDING',approved_by uuid REFERENCES public.profiles(id),source text NOT NULL DEFAULT 'MANUAL' CHECK(source IN ('MANUAL','QR')),is_demo boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(employee_id,shift_id,work_date));
CREATE TABLE IF NOT EXISTS public.attendance_corrections (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),attendance_id uuid NOT NULL REFERENCES public.attendance_records(id),old_values jsonb NOT NULL,new_values jsonb NOT NULL,reason text NOT NULL,corrected_by uuid REFERENCES public.profiles(id),approved_by uuid REFERENCES public.profiles(id),after_payroll boolean NOT NULL DEFAULT false,is_demo boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.payroll_rules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,version integer NOT NULL DEFAULT 1,config jsonb NOT NULL DEFAULT '{}'::jsonb,effective_from date NOT NULL,is_active boolean NOT NULL DEFAULT true,disclaimer_ack boolean NOT NULL DEFAULT false,is_demo boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(name,version));
CREATE TABLE IF NOT EXISTS public.payroll_periods (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),period_no text NOT NULL UNIQUE,period_start date NOT NULL,period_end date NOT NULL,status public.payroll_status NOT NULL DEFAULT 'DRAFT',rules_id uuid REFERENCES public.payroll_rules(id),rules_snapshot jsonb NOT NULL DEFAULT '{}'::jsonb,calculated_by uuid REFERENCES public.profiles(id),approved_by uuid REFERENCES public.profiles(id),needs_recalc boolean NOT NULL DEFAULT false,is_demo boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),CHECK(period_end>=period_start));
CREATE TABLE IF NOT EXISTS public.payroll_lines (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),period_id uuid NOT NULL REFERENCES public.payroll_periods(id),employee_id uuid NOT NULL REFERENCES public.employees(id),base_pay numeric(16,2) NOT NULL DEFAULT 0,overtime_pay numeric(16,2) NOT NULL DEFAULT 0,allowances numeric(16,2) NOT NULL DEFAULT 0,deductions numeric(16,2) NOT NULL DEFAULT 0,advances numeric(16,2) NOT NULL DEFAULT 0,reimbursements numeric(16,2) NOT NULL DEFAULT 0,net_pay numeric(16,2) NOT NULL DEFAULT 0,calc_breakdown jsonb NOT NULL DEFAULT '{}'::jsonb,is_demo boolean NOT NULL DEFAULT false,UNIQUE(period_id,employee_id));
CREATE TABLE IF NOT EXISTS public.payroll_adjustments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),period_id uuid NOT NULL REFERENCES public.payroll_periods(id),employee_id uuid NOT NULL REFERENCES public.employees(id),type text NOT NULL CHECK(type IN ('ALLOWANCE','DEDUCTION','ADVANCE')),amount numeric(16,2) NOT NULL,note text NOT NULL,created_by uuid REFERENCES public.profiles(id),is_demo boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.labour_allocations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),period_id uuid NOT NULL REFERENCES public.payroll_periods(id),order_id uuid NOT NULL REFERENCES public.buyer_orders(id),operation_id uuid REFERENCES public.production_operations(id),minutes numeric(14,3) NOT NULL,amount numeric(16,2) NOT NULL,basis text NOT NULL,reversed boolean NOT NULL DEFAULT false,is_demo boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.expenses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),expense_no text NOT NULL UNIQUE,employee_id uuid NOT NULL REFERENCES public.employees(id),category_id uuid REFERENCES public.cost_categories(id),order_id uuid REFERENCES public.buyer_orders(id),amount numeric(16,2) NOT NULL CHECK(amount>=0),currency text NOT NULL DEFAULT 'INR',status text NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','SUBMITTED','APPROVED','REJECTED','PAID')),receipt_file_id uuid REFERENCES public.files(id),approved_by uuid REFERENCES public.profiles(id),external_id text UNIQUE,is_demo boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE public.cost_entries ADD COLUMN IF NOT EXISTS is_demo boolean NOT NULL DEFAULT false;
ALTER TABLE public.cost_entries ADD COLUMN IF NOT EXISTS currency text NOT NULL DEFAULT 'INR';
CREATE TABLE IF NOT EXISTS public.order_cost_plans (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL REFERENCES public.buyer_orders(id),category_id uuid NOT NULL REFERENCES public.cost_categories(id),planned_amount numeric(16,2) NOT NULL,planned_qty numeric(14,3),assumptions jsonb NOT NULL DEFAULT '{}'::jsonb,is_demo boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(order_id,category_id));
CREATE TABLE IF NOT EXISTS public.cost_variance_cases (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL REFERENCES public.buyer_orders(id),category_id uuid REFERENCES public.cost_categories(id),variance_amount numeric(16,2) NOT NULL,variance_pct numeric(8,3),status text NOT NULL DEFAULT 'OPEN' CHECK(status IN ('OPEN','REVIEWED','CLOSED')),breakdown jsonb NOT NULL DEFAULT '{}'::jsonb,reviewed_by uuid REFERENCES public.profiles(id),is_demo boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());

