CREATE OR REPLACE FUNCTION private.assigned_to_operation(p_operation_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$
 SELECT EXISTS(SELECT 1 FROM public.operation_assignments oa JOIN public.employees e ON e.id=oa.employee_id JOIN public.profiles p ON p.employee_id=e.id WHERE oa.operation_id=p_operation_id AND p.id=auth.uid() AND p.status='ACTIVE' AND e.employment_status='ACTIVE')
$$;

-- RLS is default-deny. Existing identity/master/inventory grants remain narrowly controlled by earlier migrations.
DO $$ DECLARE t text; BEGIN
 FOR t IN SELECT tablename FROM pg_tables WHERE schemaname='public' LOOP EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t); END LOOP;
END $$;
DO $$ DECLARE t text; BEGIN
 FOREACH t IN ARRAY ARRAY['approval_requests','notifications','notification_preferences','email_outbox','integration_events','exceptions','tasks','files','documents','automation_rules','automation_events','automation_runs','reconciliation_reports','data_quality_flags','assistant_queries','employee_compensation','skills','employee_skills','process_skills','buyer_orders','buyer_order_lines','order_revisions','order_change_requests','feasibility_checks','production_plans','plan_material_requirements','production_operations','operation_assignments','operation_materials','operation_wip_inputs','operation_events','production_outputs','shift_handovers','waste_ledger','machine_status_log','downtime_events','maintenance_schedules','maintenance_work_orders','maintenance_parts_used','machine_telemetry','fabric_rolls','roll_material_sources','roll_genealogy','dye_lots','roll_dye_lots','roll_status_history','roll_scan_events','quality_inspections','quality_inspection_measurements','quality_defects','rework_orders','quality_incidents','quality_incident_rolls','corrective_actions','shipments','shipment_rolls','shipment_scan_events','shipment_suggestions','invoices','dispatch_reversals','attendance_records','attendance_corrections','payroll_rules','payroll_periods','payroll_lines','payroll_adjustments','labour_allocations','expenses','order_cost_plans','cost_variance_cases'] LOOP EXECUTE format('GRANT SELECT ON public.%I TO authenticated',t); END LOOP;
END $$;
CREATE POLICY buyer_orders_internal_read ON public.buyer_orders FOR SELECT TO authenticated USING (private.has_permission('orders.read') AND NOT private.has_permission('buyer.portal'));
CREATE POLICY buyer_order_lines_scoped_read ON public.buyer_order_lines FOR SELECT TO authenticated USING (private.has_permission('orders.read') AND private.has_permission('finance.read') AND NOT private.has_permission('buyer.portal'));
CREATE POLICY production_read ON public.production_operations FOR SELECT TO authenticated USING (NOT private.has_permission('buyer.portal') AND ((private.has_permission('orders.read')) OR (private.has_permission('production.read') AND (private.has_permission('production.assign') OR NOT private.has_permission('production.operate') OR private.assigned_to_operation(id)))));
CREATE POLICY operation_assignments_read ON public.operation_assignments FOR SELECT TO authenticated USING (NOT private.has_permission('buyer.portal') AND (private.has_permission('production.assign') OR private.assigned_to_operation(operation_id)));
CREATE POLICY operation_events_read ON public.operation_events FOR SELECT TO authenticated USING (NOT private.has_permission('buyer.portal') AND (private.has_permission('production.assign') OR private.assigned_to_operation(operation_id)));
CREATE POLICY production_outputs_read ON public.production_outputs FOR SELECT TO authenticated USING (NOT private.has_permission('buyer.portal') AND (private.has_permission('production.assign') OR private.assigned_to_operation(operation_id)));
CREATE POLICY operation_materials_read ON public.operation_materials FOR SELECT TO authenticated USING (private.has_permission('inventory.read') AND NOT private.has_permission('buyer.portal'));
CREATE POLICY machine_event_read ON public.machine_status_log FOR SELECT TO authenticated USING (private.has_permission('machines.read'));
CREATE POLICY downtime_read ON public.downtime_events FOR SELECT TO authenticated USING (private.has_permission('machines.read') OR private.has_permission('production.read'));
CREATE POLICY roll_read ON public.fabric_rolls FOR SELECT TO authenticated USING (private.has_permission('rolls.read') AND NOT private.has_permission('buyer.portal'));
CREATE POLICY quality_read ON public.quality_inspections FOR SELECT TO authenticated USING (private.has_permission('quality.read') AND NOT private.has_permission('buyer.portal'));
CREATE POLICY quality_defects_read ON public.quality_defects FOR SELECT TO authenticated USING (private.has_permission('quality.read') AND NOT private.has_permission('buyer.portal'));
CREATE POLICY shipment_read ON public.shipments FOR SELECT TO authenticated USING ((private.has_permission('dispatch.read') OR private.has_permission('orders.read')) AND NOT private.has_permission('buyer.portal'));
CREATE POLICY notification_self_read ON public.notifications FOR SELECT TO authenticated USING (user_id=auth.uid() AND private.is_active_user());
CREATE POLICY notification_preferences_self ON public.notification_preferences FOR SELECT TO authenticated USING (user_id=auth.uid() AND private.is_active_user());
CREATE POLICY exceptions_role_read ON public.exceptions FOR SELECT TO authenticated USING (private.has_any_permission(ARRAY['orders.read','production.read','quality.read','inventory.read','dispatch.read','audit.read']));
CREATE POLICY tasks_role_read ON public.tasks FOR SELECT TO authenticated USING (private.has_any_permission(ARRAY['tasks.manage','production.read','inventory.read','quality.read','hr.read']));
CREATE POLICY audit_role_read ON public.audit_logs FOR SELECT TO authenticated USING (private.has_permission('audit.read'));
CREATE POLICY approvals_role_read ON public.approval_requests FOR SELECT TO authenticated USING (private.has_any_permission(ARRAY['approvals.decide','users.manage','inventory.adjust_approve','purchasing.approve']));
CREATE POLICY integrations_admin_read ON public.integration_events FOR SELECT TO authenticated USING (private.has_permission('integrations.manage'));
CREATE POLICY automation_admin_read ON public.automation_rules FOR SELECT TO authenticated USING (private.has_permission('automations.manage'));
CREATE POLICY automation_events_admin_read ON public.automation_events FOR SELECT TO authenticated USING (private.has_permission('automations.manage'));
CREATE POLICY automation_runs_admin_read ON public.automation_runs FOR SELECT TO authenticated USING (private.has_permission('automations.manage'));
CREATE POLICY documents_read ON public.documents FOR SELECT TO authenticated USING (private.has_permission('orders.read') OR private.has_permission('dispatch.read') OR private.has_permission('quality.read'));
CREATE POLICY cost_entries_finance_read ON public.cost_entries FOR SELECT TO authenticated USING (private.has_permission('finance.read') AND NOT private.has_permission('buyer.portal'));
CREATE POLICY payroll_lines_private_read ON public.payroll_lines FOR SELECT TO authenticated USING (private.has_permission('compensation.read') AND NOT private.has_permission('buyer.portal'));
CREATE POLICY compensation_private_read ON public.employee_compensation FOR SELECT TO authenticated USING (private.has_permission('compensation.read') AND NOT private.has_permission('buyer.portal'));
CREATE POLICY expenses_finance_read ON public.expenses FOR SELECT TO authenticated USING (private.has_permission('expenses.approve') OR (private.has_permission('expenses.submit') AND employee_id=private.current_employee_id()));

REVOKE ALL ON ALL TABLES IN SCHEMA public FROM anon,authenticated;
