CREATE OR REPLACE FUNCTION public.rpc_buyer_list_orders() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public,pg_temp AS $$
DECLARE v_buyer uuid; v_result jsonb;
BEGIN
 PERFORM private.assert_permission('buyer.portal'); v_buyer:=private.current_buyer_id();
 IF v_buyer IS NULL THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='CODE: BUYER_SCOPE_REQUIRED'; END IF;
 SELECT COALESCE(jsonb_agg(jsonb_build_object('id',o.id,'order_number',o.order_number,'requested_date',o.requested_date,'promised_date',o.promised_date,'status',o.status,'currency',o.currency,'notes',o.notes_buyer,'created_at',o.created_at,'lines',(SELECT COALESCE(jsonb_agg(jsonb_build_object('line_no',l.line_no,'product',p.description,'colour',l.colour,'ordered_qty',l.ordered_qty,'unit',l.unit)), '[]'::jsonb) FROM public.buyer_order_lines l JOIN public.products p ON p.id=l.product_id WHERE l.order_id=o.id),'shipments',(SELECT COALESCE(jsonb_agg(jsonb_build_object('shipment_number',s.shipment_number,'status',s.status,'dispatched_at',s.dispatched_at,'tracking_reference',s.tracking_reference)), '[]'::jsonb) FROM public.shipments s WHERE s.order_id=o.id AND s.buyer_visible)) ORDER BY o.created_at DESC),'[]'::jsonb)
 INTO v_result FROM public.buyer_orders o WHERE o.buyer_id=v_buyer;
 RETURN v_result;
END $$;
CREATE OR REPLACE FUNCTION public.rpc_buyer_order_timeline(p_order_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public,pg_temp AS $$
DECLARE v_buyer uuid; v_result jsonb;
BEGIN
 PERFORM private.assert_permission('buyer.portal'); v_buyer:=private.current_buyer_id();
 SELECT jsonb_build_object('order_number',o.order_number,'status',o.status,'requested_date',o.requested_date,'promised_date',o.promised_date,'notes',o.notes_buyer,'lines',(SELECT COALESCE(jsonb_agg(jsonb_build_object('line_no',l.line_no,'product',p.description,'colour',l.colour,'ordered_qty',l.ordered_qty,'unit',l.unit)), '[]'::jsonb) FROM public.buyer_order_lines l JOIN public.products p ON p.id=l.product_id WHERE l.order_id=o.id),'shipments',(SELECT COALESCE(jsonb_agg(jsonb_build_object('shipment_number',s.shipment_number,'status',s.status,'dispatched_at',s.dispatched_at,'tracking_reference',s.tracking_reference)), '[]'::jsonb) FROM public.shipments s WHERE s.order_id=o.id AND s.buyer_visible)) INTO v_result FROM public.buyer_orders o WHERE o.id=p_order_id AND o.buyer_id=v_buyer;
 IF v_result IS NULL THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='CODE: NOT_FOUND'; END IF;
 RETURN v_result;
END $$;
GRANT EXECUTE ON FUNCTION private.assigned_to_operation(uuid) TO authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.rpc_buyer_list_orders(),public.rpc_buyer_order_timeline(uuid) TO authenticated;
